/* phrases with numbers or names in them */
const I18N_RE = [
  [/^(\d[\d,.]*) verses, best match first\. Tap one to read it in its chapter\.$/, ["$1 Verse, beste zuerst. Tippe einen an, um ihn im Kapitel zu lesen.", "$1 versículos, el mejor primero. Toca uno para leerlo en su capítulo.", "$1 versets, le meilleur d'abord. Touchez-en un pour le lire dans son chapitre.", "$1 versículos, o melhor primeiro. Toque num para ler no capítulo.", "$1 节经文，最相关的在前。点一节可在整章中阅读。", "Стихов: $1, лучшие сверху. Нажмите, чтобы прочитать в главе.", "$1개 구절, 관련도 높은 순. 누르면 장에서 읽습니다."]],
  [/^Cross-references \((\d+)\)$/, ["Querverweise ($1)", "Referencias ($1)", "Renvois ($1)", "Referências ($1)", "串珠（$1）", "Перекрёстные ссылки ($1)", "관주 ($1)"]],
  [/^Cross-references$/, ["Querverweise", "Referencias", "Renvois", "Referências", "串珠", "Перекрёстные ссылки", "관주"]],
  [/^Show all (\d+)$/, ["Alle $1 zeigen", "Mostrar las $1", "Tout afficher ($1)", "Mostrar todas as $1", "显示全部 $1 条", "Показать все $1", "$1개 모두 보기"]],
  [/^Added to the sermon list \((\d+)\)$/, ["Zur Predigtliste hinzugefügt ($1)", "Añadido a la lista del sermón ($1)", "Ajouté à la liste du sermon ($1)", "Adicionado à lista do sermão ($1)", "已加入讲道清单（$1）", "Добавлено в список проповеди ($1)", "설교 목록에 추가됨 ($1)"]],
  [/^On the passage from verse (\d+):$/, ["Zum Abschnitt ab Vers $1:", "Sobre el pasaje desde el versículo $1:", "Sur le passage à partir du verset $1 :", "Sobre o trecho a partir do versículo $1:", "关于第 $1 节起的段落：", "К отрывку со стиха $1:", "$1절부터의 단락:"]],
  [/^(.+) is ready$/, ["$1 ist bereit", "$1 está lista", "$1 est prête", "$1 está pronta", "$1 已就绪", "$1 готова", "$1 준비 완료"]],
  [/^(.+): QR code to share BibleChat$/, ["$1: QR-Code zum Teilen von BibleChat", "$1: código QR para compartir BibleChat", "$1 : code QR pour partager BibleChat", "$1: código QR para compartilhar o BibleChat", "$1：分享 BibleChat 的二维码", "$1: QR-код, чтобы поделиться BibleChat", "$1: BibleChat 공유 QR 코드"]],
  [/^QR code for (.+)$/, ["QR-Code für $1", "Código QR de $1", "Code QR de $1", "Código QR de $1", "$1 的二维码", "QR-код для $1", "$1 QR 코드"]],
  [/^(.+) background$/, null],   // "Dawn background": the colour name alone is translated
  [/^(.+?) · ([\d,.]+) verses · ([\d.]+) MB download · (.+)$/, ["$1 · $2 Verse · $3 MB · $4", "$1 · $2 versículos · $3 MB · $4", "$1 · $2 versets · $3 Mo · $4", "$1 · $2 versículos · $3 MB · $4", "$1 · $2 节 · $3 MB · $4", "$1 · стихов: $2 · $3 МБ · $4", "$1 · $2절 · $3MB · $4"]],
];
let UI_LANG = "en";
function tr(s){
  if(UI_LANG === "en" || !s) return s;
  const k = s.trim(), i = I18N_ORDER.indexOf(UI_LANG); if(i < 0) return s;
  if(I18N[k]) return s.replace(k, I18N[k][i]);
  for(const [re, out] of I18N_RE){
    const m = k.match(re); if(!m) continue;
    if(out === null){ const w = I18N[m[1]]; return w ? s.replace(k, w[i]) : s; }
    return s.replace(k, k.replace(re, out[i]));
  }
  return s;
}
/* Translate the page's own words. The original English is kept on each node, so switching back works.
   Bible text, verse lists and study content are left alone. */
const I18N_SKIP = ".coverart, #homeWhere b, #rtext, .res, #shareQuote, #welcomeQuote, #smsList, .smT, #aiPrompt, #chLink, script, style, .vt, .scof, #viRef, #books, .bl b, #smsTitle, #studyTitle, .quote, .tp b, .w, .heb, .pw, #where, #bibleChip, #churchBtn, #loveChurch h2, textarea, #langList";
function i18nText(n){
  const p = n.parentElement; if(!p || p.closest(I18N_SKIP)) return;
  if(n.__en === undefined || (n.nodeValue !== n.__tr)) n.__en = n.nodeValue;
  const t = tr(n.__en); n.__tr = t; if(n.nodeValue !== t) n.nodeValue = t;
}
function i18nEl(el){
  if(el.nodeType === 3) return i18nText(el);
  if(el.nodeType !== 1 || el.closest(I18N_SKIP)) return;
  const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT); let n;
  while((n = w.nextNode())) if(n.__en !== undefined || /[A-Za-z]/.test(n.nodeValue)) i18nText(n);
  const els = [el, ...el.querySelectorAll("[placeholder],[title],[aria-label],img[alt]")];
  for(const e of els){
    if(e.closest && e.closest(I18N_SKIP)) continue;
    for(const a of ["placeholder", "title", "aria-label", "alt"]){
      if(!e.hasAttribute || !e.hasAttribute(a)) continue;
      const key = "__en_" + a, cur = e.getAttribute(a);
      if(e[key] === undefined || e["__tr_" + a] !== cur) e[key] = cur;
      const t = tr(e[key]); e["__tr_" + a] = t; if(cur !== t) e.setAttribute(a, t);
    }
  }
}
function i18nStart(lang){
  UI_LANG = I18N_LANGS[lang] ? lang : "en";
  document.documentElement.lang = UI_LANG;
  i18nEl(document.body);
}
new MutationObserver(ms => { if(UI_LANG === "en") return; for(const m of ms) for(const n of m.addedNodes) i18nEl(n); })
  .observe(document.documentElement, {childList: true, subtree: true});
